const PROCESSING_FEE_G = 5;

// The spec states one component tariff for all components ("components -- for
// example runes and moonstones -- are insured at 250 G each, with a base
// premium of 25 G per component"), so both component rows share it.
const COMPONENT_BASE_PREMIUM_G = 25;

const BASE_PREMIUM_G: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM_G,
  moonstone: COMPONENT_BASE_PREMIUM_G,
};

const ALIKE_BLOCK_SIZE = 3;
const ALIKE_BLOCK_BASE_PREMIUM_G = 60;

export interface Customer {
  readonly yearsWithMHPCO: number;
}

export interface Item {
  readonly type: string;
}

function countByType(items: readonly Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function alikeGroupBasePremium(type: string, count: number): number {
  if (count === ALIKE_BLOCK_SIZE) {
    return ALIKE_BLOCK_BASE_PREMIUM_G;
  }
  return count * BASE_PREMIUM_G[type];
}

export function policyBasePremium(items: readonly Item[]): number {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += alikeGroupBasePremium(type, count);
  }
  return total;
}

export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  return PROCESSING_FEE_G;
}
EOF
