  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

// Resolves the spec's building-block tariff as exactly 3 alike components, not
// repeating within a larger count: the spec's larger-count examples rule out
// charging a second block. The specs assert them.
function alikeItemsBasePremium(type: string, count: number): number {
  if (count === ALIKE_BLOCK_SIZE) {
