1	import { describe, expect, it } from "vitest";
2	
3	import { policyBasePremium, premiumAfterItemModifiers, quote } from "./claim-office.js";
4	
5	// MHPCO Claim Office — complete inactive test list.
6	//
7	// Observable contracts chosen where the specification leaves a mechanism open:
8	//  * The spec states rejection cases as "the CLI exits with a non-zero status
9	//    code and writes an error description to stderr". The domain layer is
10	//    therefore specified to throw an Error (no type or message is established
11	//    by the spec, so only "throws" is asserted), and the CLI adapter is
12	//    specified to translate a thrown Error into exit code 1 + stderr text with
13	//    no `results` on stdout. Tests below name which of the two they observe.
14	//  * "rounded in the MHPCO's favor" = premium rounded up (ceil), payout
15	//    rounded down (floor); intermediates stay fractional.
16	
17	describe("MHPCO Claim Office", () => {
18	  describe("quote — processing fee and empty policy", () => {
19	    it("quotes an empty item list as premium 5 G (processing fee only)", () => {
20	      expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
21	    });
22	  });
